/* Binary search: glyph for codepoint u, or NULL. */
static inline const uint8_t *font_cjk_lookup(uint32_t u) {
    int lo = 0, hi = CJK_FONT_COUNT - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        if (cjk_font[mid].u == u) return cjk_font[mid].g;
        if (cjk_font[mid].u < u) lo = mid + 1;
        else hi = mid - 1;
    }
    return NULL;
}

